UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"A-Fib RVR: Initial Assessment","body":"[A-Fib RVR Management Steps](#/info/afib-summary) — quick-reference for rate control, cardioversion, and anticoagulation.\n\nAtrial fibrillation with rapid ventricular response (RVR) is characterized by an irregularly irregular rhythm with a ventricular rate typically 120–180 bpm. Confirm with 12-lead ECG.\n\nCOMMON PRECIPITANTS\n• Electrolyte abnormalities (K⁺, Mg²⁺)\n• Sepsis / infection\n• Pulmonary embolism\n• Thyrotoxicosis\n• Alcohol use / withdrawal\n• Pain / agitation\n• Respiratory failure / hypoxia\n• Underlying cardiac disease (valvular, ischemic, HF)\n\nINITIAL WORKUP (all patients)\n• 12-lead ECG\n• Electrolytes (K⁺, Mg²⁺)\n• TSH — thyrotoxicosis is a critical reversible precipitant\n• Troponin — screen for ACS as precipitant\n• Consider PE workup if clinical suspicion\n\nAlways treat underlying causes alongside rate control. A-Fib RVR is often a symptom of another process — rate control alone may be insufficient if the precipitant is not addressed.","citation":[1,3],"next":"afib-stability","images":[{"src":"images/afib-rvr/afib-ecg.jpg","alt":"Atrial fibrillation ECG — two lead rhythm strip","caption":"AFib: irregularly irregular rhythm, absent P waves, fibrillatory baseline (Wikimedia Commons, CC BY-SA 4.0)"}],"summary":"Irregularly irregular rhythm 120-180bpm — always treat underlying precipitants alongside rate control","skippable":true}'::jsonb
WHERE id = 'afib-start' AND tree_id = 'afib-rvr';

-- Node: ed-an-vitals (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Anorexia Nervosa - Vital Sign Red Flags","body":"**Anorexia Nervosa** causes adaptive physiological changes that can rapidly decompensate [1][2].\n\n[MARSIPAN Risk Assessment](#/calculator/marsipan-risk)\n\n**Vital Sign Red Flags (MEED 2022, RCPsych CR233):**\n\n| Finding | High Risk Threshold |\n|---------|--------------------|\n| **Heart Rate** | <40 bpm (40-50 = high concern) |\n| **QTc** | >460ms (female) / >450ms (male) |\n| **Blood Pressure** | Systolic <90 mmHg |\n| **Orthostatic Drop** | SBP drop >20 mmHg or HR rise >30 bpm |\n| **Temperature** | <35.5°C (95.9°F) |\n| **BMI** | <13 kg/m² (extreme), <15 kg/m² (high risk); peds use %median BMI <70% |\n\n**Physical Exam Findings:**\n- Lanugo (fine downy hair)\n- Muscle wasting, loss of subcutaneous fat\n- Acrocyanosis, cold extremities\n- Peripheral edema (hypoalbuminemia)\n- Russell sign (knuckle calluses from purging)\n\n**ECG abnormalities:**\n- Sinus bradycardia\n- QTc prolongation (>450ms = high risk)\n- U waves, ST changes","citation":[1,2],"next":"ed-complications","calculatorLinks":[{"id":"qtc-calculator","label":"QTc Calculator"}],"summary":"AN vital sign red flags: HR <40, SBP <90, temp <35.5°C, BMI <13 — high mortality risk","safetyLevel":"critical"}'::jsonb
WHERE id = 'ed-an-vitals' AND tree_id = 'eating-disorders';

